-- ============================================================
-- V2: 품질사양 관리(qualitySpec) 표와 시연 데이터
-- ============================================================
--
-- 대상 스키마: MQCAPUSER   위치: mqc
-- 이 파일은 그 스키마 주인으로 접속해 실행된다(앱 Flyway 또는 pdb.mjs template-schema, 운영은 DBA).
--
-- 배경:
--   품질사양 관리 화면(메뉴 qdm/qualitySpec, OASIS 서비스 qualitySpec)의 업무 기록 표다. 고객 품질사양은
--   "조건(IF) → 설계결과(THEN)" 규칙이고, 확정 뒤 SAP OMS 로 보내며(시연에서는 흉내), 주문 품질설계 때 표준 설계 기준값을 덮어쓴다.
--   표 8개: 사양 머리(TB_MQC_QSPEC), 사양 조건·결과(TB_MQC_QSPEC_TERM), 항목 사전(TB_MQC_QSPEC_ATTR),
--   표준 설계 기준값(TB_MQC_QSPEC_BASE), 고객 가명(TB_MQC_QSPEC_CUS), 주문 적용 시뮬레이션 표본 주문(TB_MQC_QSPEC_ORD),
--   변경 이력(TB_MQC_QSPEC_CHG), 전송 이력(TB_MQC_QSPEC_IF).
--   다른 담당 표에 FK 를 걸지 않는다. 표본 주문 키는 품질설계결과 화면의 주문 키(D260831027-010 등)를 그대로 쓴다.
--   품명 코드는 설계 화면 어휘(3 CCGI · 4 CCLI · G GI · L G/L · W GLX)로 맞췄다. 고객명은 가명(수요가 A~E)이다.
--   시연 데이터는 고정 시각이다(기준 2026-08-28). OMS 전송 결과는 SIM_FAIL_MSG 가 있는 사양만 실패하는 결정적 흉내다.
-- 시각 칼럼은 초 단위라 DATE 다(Oracle SQL 작성 규칙 §2). 컬럼 순서 = PK → 엔티티 필드 선언 순서.
-- ============================================================

-- 품질사양 머리: 사양번호 = 고객사-품명+순번(예 320104-L01). 현재 개정(REV)만 둔다. 지난 개정의 차이는 변경 이력에 있다.
CREATE TABLE TB_MQC_QSPEC (
    SPEC_NO       VARCHAR2(20 CHAR)    NOT NULL,
    REV           NUMBER(5)            NOT NULL,
    CUS_CD        VARCHAR2(10 CHAR)    NOT NULL,
    PRD_NM_CD     VARCHAR2(2 CHAR)     NOT NULL,
    RAW_TEXT      VARCHAR2(1000 CHAR)  NOT NULL,
    STATUS        VARCHAR2(10 CHAR)    NOT NULL,
    FAIL_MSG      VARCHAR2(200 CHAR),
    SIM_FAIL_MSG  VARCHAR2(200 CHAR),
    REG_USR_NM    VARCHAR2(50 CHAR)    NOT NULL,
    REG_DTTM      DATE                 NOT NULL,
    MOD_USR_NM    VARCHAR2(50 CHAR)    NOT NULL,
    MOD_DTTM      DATE                 NOT NULL,
    CONSTRAINT PK_MQC_QSPEC PRIMARY KEY (SPEC_NO),
    CONSTRAINT CK_MQC_QSPEC_STATUS CHECK (STATUS IN ('DRAFT', 'CONF', 'SENT', 'FAIL'))
);
COMMENT ON TABLE TB_MQC_QSPEC IS '품질사양(현재 개정)';
COMMENT ON COLUMN TB_MQC_QSPEC.STATUS IS 'DRAFT 작성중 · CONF 확정 · SENT 전송완료 · FAIL 전송실패';
COMMENT ON COLUMN TB_MQC_QSPEC.SIM_FAIL_MSG IS '시연용: 값이 있으면 OMS 전송이 늘 이 메시지로 실패한다';

-- 사양 조건(IF)·설계결과(THEN). ATTR_CD 가 비면 항목 사전에 없는(미매핑) 항목이다.
CREATE TABLE TB_MQC_QSPEC_TERM (
    SPEC_NO   VARCHAR2(20 CHAR)   NOT NULL,
    SIDE      VARCHAR2(4 CHAR)    NOT NULL,
    SEQ       NUMBER(3)           NOT NULL,
    ATTR_CD   VARCHAR2(20 CHAR),
    ATTR_NM   VARCHAR2(50 CHAR)   NOT NULL,
    OP        VARCHAR2(2 CHAR)    NOT NULL,
    VAL       VARCHAR2(200 CHAR)  NOT NULL,
    UNIT      VARCHAR2(10 CHAR),
    CONSTRAINT PK_MQC_QSPEC_TERM PRIMARY KEY (SPEC_NO, SIDE, SEQ),
    CONSTRAINT CK_MQC_QSPEC_TERM_SIDE CHECK (SIDE IN ('IF', 'THEN'))
);
CREATE INDEX IX_MQC_QSPEC_TERM_ATTR ON TB_MQC_QSPEC_TERM (ATTR_CD);
COMMENT ON TABLE TB_MQC_QSPEC_TERM IS '품질사양 조건(IF)·설계결과(THEN)';
COMMENT ON COLUMN TB_MQC_QSPEC_TERM.OP IS '= · ~(범위, 양끝 포함) · ≥ · ≤ · > · <';

-- 항목 사전: 사양 문장에서 알아보는 항목(한글명·시스템 코드). 사용 중지 항목은 파서가 알아보지 않는다.
CREATE TABLE TB_MQC_QSPEC_ATTR (
    ATTR_CD      VARCHAR2(20 CHAR)   NOT NULL,
    ATTR_NM      VARCHAR2(50 CHAR)   NOT NULL,
    ATTR_KIND    VARCHAR2(10 CHAR)   NOT NULL,
    DATA_TYPE    VARCHAR2(10 CHAR)   NOT NULL,
    DATA_LEN     VARCHAR2(10 CHAR),
    UNIT         VARCHAR2(10 CHAR),
    DESCRIPTION  VARCHAR2(200 CHAR),
    USE_YN       VARCHAR2(1 CHAR)    NOT NULL,
    SEQ          NUMBER(5)           NOT NULL,
    CONSTRAINT PK_MQC_QSPEC_ATTR PRIMARY KEY (ATTR_CD),
    CONSTRAINT UK_MQC_QSPEC_ATTR_NM UNIQUE (ATTR_NM),
    CONSTRAINT CK_MQC_QSPEC_ATTR_KIND CHECK (ATTR_KIND IN ('COND', 'RESULT', 'BOTH')),
    CONSTRAINT CK_MQC_QSPEC_ATTR_TYPE CHECK (DATA_TYPE IN ('VARCHAR2', 'NUMBER', 'CHAR', 'DATE')),
    CONSTRAINT CK_MQC_QSPEC_ATTR_USE CHECK (USE_YN IN ('Y', 'N'))
);
COMMENT ON TABLE TB_MQC_QSPEC_ATTR IS '품질사양 항목 사전(코드 사전)';

-- 표준 설계 기준값: 사양이 없을 때 쓰는 설계결과 기본값. 맞는 사양이 사양번호 순으로 덮어쓴다(뒤 사양 우선).
CREATE TABLE TB_MQC_QSPEC_BASE (
    ATTR_CD   VARCHAR2(20 CHAR)   NOT NULL,
    BASE_VAL  VARCHAR2(100 CHAR)  NOT NULL,
    REMARK    VARCHAR2(200 CHAR),
    SEQ       NUMBER(5)           NOT NULL,
    CONSTRAINT PK_MQC_QSPEC_BASE PRIMARY KEY (ATTR_CD)
);
COMMENT ON TABLE TB_MQC_QSPEC_BASE IS '품질사양 표준 설계 기준값';

-- 고객 가명: 시연에서는 실명 대신 수요가 A~E 로 보인다.
CREATE TABLE TB_MQC_QSPEC_CUS (
    CUS_CD  VARCHAR2(10 CHAR)  NOT NULL,
    CUS_NM  VARCHAR2(50 CHAR)  NOT NULL,
    SEQ     NUMBER(5)          NOT NULL,
    CONSTRAINT PK_MQC_QSPEC_CUS PRIMARY KEY (CUS_CD)
);
COMMENT ON TABLE TB_MQC_QSPEC_CUS IS '품질사양 고객(시연 가명)';

-- 주문 적용 시뮬레이션 표본: OMS 에서 받은 주문 줄과 사양 조건 항목값(ATTRS_JSON = {"항목코드":"값"}).
CREATE TABLE TB_MQC_QSPEC_ORD (
    ORD_NO      VARCHAR2(20 CHAR)    NOT NULL,
    CUS_CD      VARCHAR2(10 CHAR)    NOT NULL,
    PRD_NM_CD   VARCHAR2(2 CHAR)     NOT NULL,
    QTY         VARCHAR2(20 CHAR),
    ATTRS_JSON  VARCHAR2(2000 CHAR)  NOT NULL,
    RECV_DTTM   DATE                 NOT NULL,
    CONSTRAINT PK_MQC_QSPEC_ORD PRIMARY KEY (ORD_NO)
);
COMMENT ON TABLE TB_MQC_QSPEC_ORD IS '품질사양 주문 적용 시뮬레이션 표본 주문(OMS 수신)';

-- 변경 이력: 등록·확정·수정·개정·OMS 전송·OMS 전송 실패·삭제. CHANGES_JSON = [{"item","before","after"}].
CREATE TABLE TB_MQC_QSPEC_CHG (
    CHG_ID        NUMBER(19)          GENERATED BY DEFAULT AS IDENTITY,
    SPEC_NO       VARCHAR2(20 CHAR)   NOT NULL,
    REV           NUMBER(5)           NOT NULL,
    ACTION_CD     VARCHAR2(10 CHAR)   NOT NULL,
    CHANGES_JSON  CLOB                NOT NULL,
    WORKER_NM     VARCHAR2(50 CHAR)   NOT NULL,
    CHG_DTTM      DATE                NOT NULL,
    CONSTRAINT PK_MQC_QSPEC_CHG PRIMARY KEY (CHG_ID),
    CONSTRAINT CK_MQC_QSPEC_CHG_ACTION CHECK (ACTION_CD IN ('REG', 'CONF', 'MOD', 'REV', 'SEND', 'SEND_FAIL', 'DEL'))
);
CREATE INDEX IX_MQC_QSPEC_CHG_SPEC ON TB_MQC_QSPEC_CHG (SPEC_NO);
CREATE INDEX IX_MQC_QSPEC_CHG_DTTM ON TB_MQC_QSPEC_CHG (CHG_DTTM);
COMMENT ON TABLE TB_MQC_QSPEC_CHG IS '품질사양 변경 이력';

-- 전송 이력(I/F): MES→OMS 사양 송신, OMS→MES 주문 수신. I/F 번호 = IF-YYYYMMDD-순번(날짜마다 01부터).
CREATE TABLE TB_MQC_QSPEC_IF (
    IF_NO       VARCHAR2(20 CHAR)   NOT NULL,
    DIRECTION   VARCHAR2(10 CHAR)   NOT NULL,
    TARGET      VARCHAR2(40 CHAR)   NOT NULL,
    SPEC_NO     VARCHAR2(20 CHAR),
    REV         NUMBER(5),
    ORD_NO      VARCHAR2(20 CHAR),
    IF_RESULT   VARCHAR2(4 CHAR)    NOT NULL,
    MSG         VARCHAR2(200 CHAR)  NOT NULL,
    ELAPSED_MS  NUMBER(6)           NOT NULL,
    PAYLOAD     CLOB,
    IF_DTTM     DATE                NOT NULL,
    CONSTRAINT PK_MQC_QSPEC_IF PRIMARY KEY (IF_NO),
    CONSTRAINT CK_MQC_QSPEC_IF_DIR CHECK (DIRECTION IN ('MES_OMS', 'OMS_MES')),
    CONSTRAINT CK_MQC_QSPEC_IF_RESULT CHECK (IF_RESULT IN ('OK', 'FAIL'))
);
CREATE INDEX IX_MQC_QSPEC_IF_SPEC ON TB_MQC_QSPEC_IF (SPEC_NO);
CREATE INDEX IX_MQC_QSPEC_IF_DTTM ON TB_MQC_QSPEC_IF (IF_DTTM);
COMMENT ON TABLE TB_MQC_QSPEC_IF IS '품질사양 전송 이력(OMS I/F)';

-- ============================================================
